func AtomicCounter(numOps int) int64 {
	var counter int64
	var wg sync.WaitGroup
	for i := 0; i < numOps; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			atomic.AddInt64(&counter, 1)
		}()
	}
	wg.Wait()
	return counter
}

func ConcurrentAppend(count int) []int {
	var mu sync.Mutex
	var res []int
	var wg sync.WaitGroup
	for i := 0; i < count; i++ {
		wg.Add(1)
		go func(val int) {
			defer wg.Done()
			mu.Lock()
			res = append(res, val)
			mu.Unlock()
		}(i)
	}
	wg.Wait()
	return res
}

