func BufferedSum(nums []int) int {
	ch := make(chan int, len(nums))
	for _, n := range nums {
		ch <- n
	}
	close(ch)
	sum := 0
	for n := range ch {
		sum += n
	}
	return sum
}

func SelectWithTimeout(ch <-chan int, timeout time.Duration) (int, bool) {
	select {
	case val := <-ch:
		return val, true
	case <-time.After(timeout):
		return 0, false
	}
}

func WorkerPool(numJobs, numWorkers int) int {
	jobs := make(chan int, numJobs)
	results := make(chan int, numJobs)
	for w := 0; w < numWorkers; w++ {
		go func() {
			for j := range jobs {
				results <- j * 2
			}
		}()
	}
	for j := 0; j < numJobs; j++ {
		jobs <- j
	}
	close(jobs)
	sum := 0
	for a := 0; a < numJobs; a++ {
		sum += <-results
	}
	return sum
}

