package main

import "sync"

func SquareWorkerPool(inputs []int) []int {
	res := make([]int, len(inputs))
	var wg sync.WaitGroup
	for i, val := range inputs {
		wg.Add(1)
		go func(idx, v int) {
			defer wg.Done()
			res[idx] = v * v
		}(i, val)
	}
	wg.Wait()
	return res
}

func MaybeError(flag bool) (string, error) {
	if flag {
		return "success", nil
	}
	return "", nil
}

func DeferLIFO() []int {
	var out []int
	for i := 1; i <= 3; i++ {
		defer func(val int) {
			out = append(out, val)
		}(i)
	}
	return out
}

